CREATE TABLE public.fishing_species (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    scientific_name text,
    category text,
    subcategory text,
    description text,
    image_url text,
    habitat text,
    average_size text,
    record_size text,
    best_seasons text[] DEFAULT '{}'::text[] NOT NULL,
    peak_season text,
    recommended_bait text[] DEFAULT '{}'::text[] NOT NULL,
    recommended_lures text[] DEFAULT '{}'::text[] NOT NULL,
    techniques text[] DEFAULT '{}'::text[] NOT NULL,
    difficulty text,
    fun_fact text,
    conservation text,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE ONLY public.fishing_species ADD CONSTRAINT fishing_species_name_key UNIQUE (name);

ALTER TABLE ONLY public.fishing_species ADD CONSTRAINT fishing_species_pkey PRIMARY KEY (id);

